CREATE TEMP TABLE care_et1_before ON COMMIT DROP AS SELECT jsonb_build_object('subscriptions',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.subscriptions t ),'loyalty_cards',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.loyalty_cards t ),'offers',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.offers t ),'cafes',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.cafes t ),'brand_feature_overrides',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.brand_feature_overrides t ),'menu_products',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.menu_products t WHERE cafe_id NOT IN('16639d20-bb5e-4fea-891b-25ad80ecd0e0')),'menu_categories',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.menu_categories t WHERE cafe_id NOT IN('16639d20-bb5e-4fea-891b-25ad80ecd0e0')),'cafe_settings',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_settings t WHERE cafe_id NOT IN('294d1c16-83d9-436f-bfc7-982e4a98f754','16639d20-bb5e-4fea-891b-25ad80ecd0e0')),'cafe_custom_identity',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_custom_identity t WHERE cafe_id NOT IN('294d1c16-83d9-436f-bfc7-982e4a98f754','16639d20-bb5e-4fea-891b-25ad80ecd0e0')),'cafe_loyalty_programs',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_loyalty_programs t WHERE cafe_id NOT IN('294d1c16-83d9-436f-bfc7-982e4a98f754','16639d20-bb5e-4fea-891b-25ad80ecd0e0')),'cafe_loyalty_experience',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_loyalty_experience t WHERE cafe_id NOT IN('294d1c16-83d9-436f-bfc7-982e4a98f754','16639d20-bb5e-4fea-891b-25ad80ecd0e0'))) snapshot;
